package hu.boltseged.billing;
import hu.boltseged.account.Account; import org.junit.jupiter.api.Test; import java.math.*; import static org.junit.jupiter.api.Assertions.*;
class PricingCalculatorTest { @Test void zeroMarkupPreservesCost(){Account a=new Account("x","x@example.com","hash","CUSTOMER");assertEquals(new BigDecimal("12.50"),PricingCalculator.customerPrice(a,new BigDecimal("12.5")));} @Test void percentageMarkup(){Account a=new Account("x","x@example.com","hash","CUSTOMER");a.update("x",null,null,"x","x@example.com","PERCENTAGE",new BigDecimal("10"));assertEquals(new BigDecimal("11000.00"),PricingCalculator.customerPrice(a,new BigDecimal("10000")));} @Test void fixedMarkup(){Account a=new Account("x","x@example.com","hash","CUSTOMER");a.update("x",null,null,"x","x@example.com","FIXED",new BigDecimal("1500"));assertEquals(new BigDecimal("11500.00"),PricingCalculator.customerPrice(a,new BigDecimal("10000")));} @Test void snapshotValueIsIndependentFromLaterRule(){Account a=new Account("x","x@example.com","hash","CUSTOMER");a.update("x",null,null,"x","x@example.com","PERCENTAGE",new BigDecimal("10"));BigDecimal snapshot=PricingCalculator.customerPrice(a,new BigDecimal("10000"));a.update("x",null,null,"x","x@example.com","FIXED",new BigDecimal("1500"));assertEquals(new BigDecimal("11000.00"),snapshot);assertEquals(new BigDecimal("11500.00"),PricingCalculator.customerPrice(a,new BigDecimal("10000")));} }
